//! Golden tests of unit W2-04: the C# oracle outputs `tests/golden/l10n-{catalog,localizer,loader,generator,
//! flat-json}.json` (generated by `tools/oracle-cs/Commands/W2-04.cs` from the C# code at baseline d92d6aae).
//!
//! The `warnings` of the oracle carry two masks (`<ROOT>` and `(*)` for .NET exception text) that the Rust side
//! applies to its own warnings before comparing.

#[path = "../build/keygen.rs"]
#[allow(dead_code)] // the whole generator module is compiled here, the tests use part of it
mod keygen;

