// ---------------------------------------------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------------------------------------------

/// `{{DEEP:n}}` -> n nested arrays, `{{DEEPOBJ:n}}` -> n nested objects ending in the number 1 (oracle `L10nExpand`).
fn expand(json: &str) -> String {
    let mut out = String::new();
    let mut rest = json;
    while let Some(start) = rest.find("{{DEEP") {
        out.push_str(&rest[..start]);
        let tail = &rest[start..];
        let (kind, after) = if let Some(t) = tail.strip_prefix("{{DEEPOBJ:") {
            ('o', t)
        } else if let Some(t) = tail.strip_prefix("{{DEEP:") {
            ('a', t)
        } else {
            // Not one of ours (e.g. `{{DEEP_ARRAYS}}`): keep the text.
            out.push_str("{{DEEP");
            rest = &tail["{{DEEP".len()..];
            continue;
        };
        let close = after.find("}}").expect("unterminated DEEP token");
        let n: usize = after[..close].parse().expect("DEEP count");
        match kind {
            'a' => {
                out.push_str(&"[".repeat(n));
                out.push_str(&"]".repeat(n));
            }
            _ => {
                out.push_str(&"{\"a\":".repeat(n));
                out.push('1');
                out.push_str(&"}".repeat(n));
            }
        }
        rest = &after[close + 2..];
    }
    out.push_str(rest);
    out
}

/// The oracle's `L10nMask`: root path => `<ROOT>`, and the text of .NET exception messages in parentheses => `(*)`.
fn mask(warning: &str, root: Option<&str>) -> String {
    let mut w = match root {
        Some(root) => warning.replace(root, "<ROOT>"),
        None => warning.to_owned(),
    };
    // Regex `^(.*(?:invalid JSON|unreadable text|cannot read|cannot list files)) \(.*\)$` (greedy, single line).
    let mut best: Option<usize> = None;
    for kw in ["invalid JSON", "unreadable text", "cannot read", "cannot list files"] {
        let pattern = format!("{kw} (");
        if let Some(pos) = w.rfind(&pattern) {
            let end = pos + kw.len();
            if best.is_none_or(|b| end > b) {
                best = Some(end);
            }
        }
    }
    if let Some(end) = best
        && w.ends_with(')')
    {
        w.truncate(end);
        w.push_str(" (*)");
    }
    w
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap_or_else(|| panic!("not an array: {v}"))
        .iter()
        .map(|s| s.as_str().unwrap_or_else(|| panic!("not a string: {s}")).to_owned())
        .collect()
}

fn asset_text(asset: &str) -> String {
    let path = golden::repo_root().join("assets").join(asset);
    std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

fn plural_name(rule: PluralRule) -> &'static str {
    rule.name()
}

