#[test]
fn catalog_try_parse_matches_the_csharp_oracle() {
    let g = golden::load("l10n-catalog");
    for case in &g.cases {
        let id = golden::str_of(case, "id");
        let mut json = golden::str_of(case, "json").to_owned();
        if let Some(repeat) = case.get("repeat") {
            let ch = repeat["char"].as_str().expect("repeat char");
            let count = repeat["count"].as_u64().expect("repeat count") as usize;
            json = json.replace("{{REPEAT}}", &ch.repeat(count));
        }
        let json = expand(&json);
        let source = match case.get("source_repeat") {
            Some(sr) => sr["char"]
                .as_str()
                .expect("char")
                .repeat(sr["count"].as_u64().expect("count") as usize),
            None => case
                .get("source")
                .and_then(Value::as_str)
                .unwrap_or("test.json")
                .to_owned(),
        };
        let mut warnings = Vec::new();
        let parsed = LanguageCatalog::try_parse(&json, &source, &mut warnings);
        let warnings: Vec<String> = warnings.iter().map(|w| mask(w, None)).collect();
        assert_eq!(warnings, strings(&case["warnings"]), "warnings of {id}");
        assert_eq!(parsed.is_some(), golden::bool_of(case, "ok"), "ok of {id}");
        if let Some(catalog) = parsed {
            let expected = &case["catalog"];
            assert_eq!(catalog.code(), expected["code"].as_str().unwrap(), "code of {id}");
            assert_eq!(catalog.name(), expected["name"].as_str().unwrap(), "name of {id}");
            assert_eq!(
                catalog.native_name(),
                expected["nativeName"].as_str().unwrap(),
                "nativeName of {id}"
            );
            assert_eq!(
                catalog.native_name_declared(),
                expected["nativeNameDeclared"].as_bool().unwrap(),
                "nativeNameDeclared of {id}"
            );
            assert_eq!(
                plural_name(catalog.plural()),
                expected["plural"].as_str().unwrap(),
                "plural of {id}"
            );
            assert_eq!(
                catalog.plural_declared(),
                expected["pluralDeclared"].as_bool().unwrap(),
                "pluralDeclared of {id}"
            );
            assert_eq!(
                catalog.authors(),
                strings(&expected["authors"]).as_slice(),
                "authors of {id}"
            );
            let entries: Vec<(String, String)> = expected["entries"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| (p[0].as_str().unwrap().to_owned(), p[1].as_str().unwrap().to_owned()))
                .collect();
            assert_eq!(catalog.entries(), entries.as_slice(), "entries of {id}");
        }
    }
}

