// l10n-localizer
// ---------------------------------------------------------------------------------------------------------------

fn loc_value(v: &Value) -> LocValue {
    match v {
        Value::String(s) => LocValue::Str(s.clone()),
        Value::Number(n) => LocValue::Int(n.as_i64().expect("integer arg")),
        Value::Object(o) => match o["t"].as_str().expect("arg type") {
            "double" => match o.get("bits") {
                Some(bits) => LocValue::F64(f64::from_bits(
                    u64::from_str_radix(bits.as_str().expect("bits"), 16).expect("hex bits"),
                )),
                None => LocValue::F64(o["v"].as_f64().expect("double")),
            },
            "bool" => LocValue::Bool(o["v"].as_bool().expect("bool")),
            "int" => LocValue::Int(o["v"].as_i64().expect("int")),
            other => panic!("arg type {other}"),
        },
        other => panic!("arg {other}"),
    }
}

fn loc_args(args: Option<&Value>) -> Vec<LocArg> {
    match args.and_then(Value::as_object) {
        Some(o) => o.iter().map(|(k, v)| LocArg::new(k.clone(), loc_value(v))).collect(),
        None => Vec::new(),
    }
}

fn parse_catalog(json: &str) -> LanguageCatalog {
    let mut warnings = Vec::new();
    LanguageCatalog::try_parse(json, "test", &mut warnings)
        .unwrap_or_else(|| panic!("catalog in golden input is invalid: {}", warnings.join("; ")))
}

/// Runs the probes of a case and compares with the expected probe results.
fn check_probes(localizer: &Localizer, probes: &Value, id: &str) {
    let culture = NumberCulture::invariant();
    for probe in probes.as_array().expect("probes") {
        let key = golden::str_of(probe, "key");
        let op = golden::str_of(probe, "op");
        let expected = &probe["out"];
        match op {
            "get" => assert_eq!(localizer.get(key), expected.as_str().unwrap(), "{id}: get {key}"),
            "contains" => assert_eq!(
                localizer.contains(key),
                expected.as_bool().unwrap(),
                "{id}: contains {key}"
            ),
            "format" => assert_eq!(
                localizer.format_with(key, &loc_args(probe.get("args")), &culture),
                expected.as_str().unwrap(),
                "{id}: format {key}"
            ),
            "plural" => assert_eq!(
                localizer.format_plural_with(
                    key,
                    golden::i64_of(probe, "count"),
                    &loc_args(probe.get("args")),
                    &culture
                ),
                expected.as_str().unwrap(),
                "{id}: plural {key} {}",
                probe["count"]
            ),
            other => panic!("probe op {other}"),
        }
    }
}

#[test]
fn localizer_matches_the_csharp_oracle() {
    let g = golden::load("l10n-localizer");
    for case in &g.cases {
        let id = golden::str_of(case, "id");
        let english_text = match case.get("english_asset").and_then(Value::as_str) {
            Some(asset) => asset_text(asset),
            None => golden::str_of(case, "english").to_owned(),
        };
        let english = parse_catalog(&english_text);
        let mut overlays: Vec<LanguageCatalog> = case
            .get("overlays")
            .map(strings)
            .unwrap_or_default()
            .iter()
            .map(|o| parse_catalog(o))
            .collect();
        overlays.extend(
            case.get("overlay_assets")
                .map(strings)
                .unwrap_or_default()
                .iter()
                .map(|a| parse_catalog(&asset_text(a))),
        );
        let prior = case.get("prior_warnings").map(strings).unwrap_or_default();
        let mut localizer = Localizer::create(&english, &overlays, &prior);
        match case.get("mode").and_then(Value::as_str) {
            Some("pseudo") => localizer = create_pseudo(&localizer),
            Some("showkeys") => localizer = create_show_keys(&localizer),
            Some(other) => panic!("mode {other}"),
            None => {}
        }
        let out = &case["out"];
        assert_eq!(localizer.code(), out["code"].as_str().unwrap(), "code of {id}");
        assert_eq!(
            localizer.native_name(),
            out["nativeName"].as_str().unwrap(),
            "nativeName of {id}"
        );
        assert_eq!(
            plural_name(localizer.plural()),
            out["plural"].as_str().unwrap(),
            "plural of {id}"
        );
        let warnings: Vec<String> = localizer.warnings().iter().map(|w| mask(w, None)).collect();
        assert_eq!(warnings, strings(&out["warnings"]), "warnings of {id}");
        let mut keys: Vec<&str> = localizer.keys().collect();
        keys.sort_unstable();
        let expected_keys = strings(&out["keys"]);
        assert_eq!(
            keys,
            expected_keys.iter().map(String::as_str).collect::<Vec<_>>(),
            "keys of {id}"
        );
        check_probes(&localizer, &out["probes"], id);
    }
}

// ---------------------------------------------------------------------------------------------------------------
// l10n-loader
// ---------------------------------------------------------------------------------------------------------------

const ROOT: &str = r"C:\OracleL10n";

fn add_files(fs: &FakeFileSystem, dir: &std::path::Path, files: Option<&Value>) {
    fs.add_dir(dir);
    let Some(files) = files.and_then(Value::as_object) else {
        return;
    };
    for (name, spec) in files {
        let path = dir.join(name);
        match spec {
            Value::String(text) => fs.add_file(&path, text.as_bytes()),
            Value::Object(o) => {
                let json = o["json"].as_str().expect("json");
                if let Some(pad) = o.get("pad_to_bytes").and_then(Value::as_u64) {
                    let mut bytes = vec![b' '; pad as usize];
                    bytes[..json.len()].copy_from_slice(json.as_bytes());
                    fs.add_file(&path, &bytes);
                } else if o.get("bom").and_then(Value::as_bool) == Some(true) {
                    let mut bytes = vec![0xEF, 0xBB, 0xBF];
                    bytes.extend_from_slice(json.as_bytes());
                    fs.add_file(&path, &bytes);
                } else {
                    fs.add_file(&path, json.as_bytes());
                }
            }
            other => panic!("file spec {other}"),
        }
    }
}

fn culture_of(op: &Value) -> Option<UiCulture> {
    op.get("culture").and_then(Value::as_str).map(|_| UiCulture {
        name: golden::str_of(op, "culture_name").to_owned(),
        two_letter_iso_language_name: golden::str_of(op, "culture_two_letter").to_owned(),
    })
}

#[test]
fn loader_matches_the_csharp_oracle() {
    let g = golden::load("l10n-loader");
    for case in &g.cases {
        let id = golden::str_of(case, "id");
        let root = PathBuf::from(ROOT);
        let shipped = root.join("App").join("Languages");
        let user = root.join("User").join("Languages");
        let fs = Arc::new(FakeFileSystem::new());
        let flag = |k: &str| case.get(k).and_then(Value::as_bool) == Some(true);
        if !flag("shipped_missing") {
            add_files(&fs, &shipped, case.get("shipped"));
        }
        let user_dir = if flag("user_null") {
            None
        } else {
            if !flag("user_missing") {
                add_files(&fs, &user, case.get("user"));
            }
            Some(user.clone())
        };
        for locked in case.get("locked").map(strings).unwrap_or_default() {
            fs.fail_locked(FsOp::ReadText, root.join(locked.replace('/', "\\")));
        }
        let file_system: Arc<dyn FileSystem> = fs.clone();
        let loader = LanguageLoader::new(file_system, shipped, user_dir);
        for op in case["ops"].as_array().unwrap() {
            let culture = culture_of(op);
            let code = op.get("code").and_then(Value::as_str);
            match golden::str_of(op, "op") {
                "discover" => {
                    let found = loader.discover_languages();
                    let expected = op["out"].as_array().unwrap();
                    assert_eq!(found.len(), expected.len(), "{id}: discover count");
                    for (f, e) in found.iter().zip(expected) {
                        assert_eq!(f.code, e["code"].as_str().unwrap(), "{id}: code");
                        assert_eq!(f.name, e["name"].as_str().unwrap(), "{id}: name");
                        assert_eq!(f.native_name, e["nativeName"].as_str().unwrap(), "{id}: nativeName");
                        assert_eq!(
                            f.is_user_provided,
                            e["isUserProvided"].as_bool().unwrap(),
                            "{id}: isUserProvided of {}",
                            f.code
                        );
                    }
                }
                "resolve" => {
                    assert_eq!(
                        loader.resolve(code, culture.as_ref()),
                        op["out"].as_str().unwrap(),
                        "{id}: resolve {code:?} {culture:?}"
                    );
                }
                "load" => {
                    let localizer = loader.load(code, culture.as_ref());
                    let out = &op["out"];
                    assert_eq!(localizer.code(), out["code"].as_str().unwrap(), "{id}: code");
                    assert_eq!(
                        localizer.native_name(),
                        out["nativeName"].as_str().unwrap(),
                        "{id}: nativeName"
                    );
                    assert_eq!(
                        plural_name(localizer.plural()),
                        out["plural"].as_str().unwrap(),
                        "{id}: plural"
                    );
                    let warnings: Vec<String> = localizer.warnings().iter().map(|w| mask(w, Some(ROOT))).collect();
                    assert_eq!(warnings, strings(&out["warnings"]), "{id}: warnings");
                    check_probes(&localizer, &out["probes"], id);
                }
                other => panic!("loader op {other}"),
            }
        }
    }
}

// ---------------------------------------------------------------------------------------------------------------
// l10n-generator
// ---------------------------------------------------------------------------------------------------------------

fn utf16_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    a.encode_utf16().cmp(b.encode_utf16())
}

fn sorted_diagnostics(plan: &keygen::Plan) -> Vec<(String, String)> {
    let mut v: Vec<(String, String)> = plan
        .diagnostics
        .iter()
        .map(|d| (d.id.to_owned(), d.message.clone()))
        .collect();
    v.sort_by(|a, b| utf16_cmp(&a.0, &b.0).then_with(|| utf16_cmp(&a.1, &b.1)));
    v
}

/// `en.json` files only (the generator does `Path.GetFileName(f.Path)` and compares ignoring case).
fn catalog_inputs(files: &[Value]) -> Vec<keygen::CatalogInput> {
    files
        .iter()
        .filter(|f| eq_ignore_case(get_file_name(f["path"].as_str().unwrap()), "en.json"))
        .map(|f| {
            let content = match f.get("asset").and_then(Value::as_str) {
                Some(asset) => asset_text(asset),
                None => expand(f["json"].as_str().unwrap()),
            };
            keygen::CatalogInput {
                path: f["path"].as_str().unwrap().to_owned(),
                content: Some(content),
            }
        })
        .collect()
}

#[test]
fn generator_plan_matches_the_csharp_oracle() {
    let g = golden::load("l10n-generator");
    for case in &g.cases {
        let id = golden::str_of(case, "id");
        if case.get("fuzz_placeholders").is_some() {
            continue;
        }
        let inputs = catalog_inputs(case["files"].as_array().unwrap());
        let plan = keygen::plan(&inputs);
        let expected: Vec<(String, String)> = case["diagnostics"]
            .as_array()
            .unwrap()
            .iter()
            .map(|d| {
                (
                    golden::str_of(d, "id").to_owned(),
                    golden::str_of(d, "message").to_owned(),
                )
            })
            .collect();
        assert_eq!(sorted_diagnostics(&plan), expected, "diagnostics of {id}");
        assert_eq!(plan.generated, golden::bool_of(case, "generated"), "generated of {id}");
        if !plan.generated {
            continue;
        }
        let consts: Vec<(String, String)> = plan.consts.iter().map(|c| (c.ident.clone(), c.key.clone())).collect();
        let expected_consts: Vec<(String, String)> = case["consts"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| {
                (
                    golden::str_of(c, "ident").to_owned(),
                    golden::str_of(c, "key").to_owned(),
                )
            })
            .collect();
        assert_eq!(consts, expected_consts, "consts of {id}");
        let expected_members = case["members"].as_array().unwrap();
        assert_eq!(plan.members.len(), expected_members.len(), "member count of {id}");
        for (m, e) in plan.members.iter().zip(expected_members) {
            assert_eq!(m.ident, golden::str_of(e, "ident"), "member ident of {id}");
            match (&m.kind, golden::str_of(e, "kind")) {
                (keygen::MemberKind::Simple { key }, "simple") => {
                    assert_eq!(key, golden::str_of(e, "key"), "member key of {id}");
                }
                (keygen::MemberKind::Plural { base }, "plural") => {
                    assert_eq!(base, golden::str_of(e, "base"), "member base of {id}");
                }
                (kind, expected) => panic!("{id}: member {} is {kind:?}, expected {expected}", m.ident),
            }
            assert_eq!(m.params, strings(&e["params"]), "params of {} in {id}", m.ident);
        }
        // Rendering must not panic and must name every member.
        let tr = keygen::render_tr(&plan);
        for m in &plan.members {
            assert!(
                tr.contains(&format!("fn {}(", keygen::fn_name(&m.ident))),
                "{id}: fn for {}",
                m.ident
            );
        }
        assert_eq!(
            keygen::render_keys(&plan).lines().count(),
            plan.consts.len() + 1,
            "{id}: keys lines"
        );
    }
}

#[test]
fn generator_placeholders_agree_with_the_runtime_parser() {
    let g = golden::load("l10n-generator");
    let mut fuzz_cases = 0;
    for case in g.cases.iter().filter(|c| c.get("fuzz_placeholders").is_some()) {
        fuzz_cases += 1;
        let id = golden::str_of(case, "id");
        let texts = strings(&case["texts"]);
        let rejects = case["generator_rejects"].as_array().unwrap();
        let accepts = case["runtime_accepts"].as_array().unwrap();
        let placeholders = case["placeholders"].as_array().unwrap();
        assert_eq!(texts.len(), rejects.len());
        for (i, text) in texts.iter().enumerate() {
            let generator = keygen::try_get_placeholders(text);
            let runtime = LocTemplate::try_parse(text);
            assert_eq!(
                generator.is_none(),
                rejects[i].as_bool().unwrap(),
                "{id}: generator verdict of {text:?}"
            );
            assert_eq!(
                runtime.is_some(),
                accepts[i].as_bool().unwrap(),
                "{id}: runtime verdict of {text:?}"
            );
            assert_eq!(generator.is_none(), runtime.is_none(), "{id}: agreement on {text:?}");
            match (&generator, &runtime) {
                (Some(names), Some(template)) => {
                    let mut dedup: Vec<String> = Vec::new();
                    for n in template.placeholder_names() {
                        if !dedup.contains(n) {
                            dedup.push(n.clone());
                        }
                    }
                    assert_eq!(names, &dedup, "{id}: placeholders of {text:?}");
                    assert_eq!(
                        *names,
                        strings(&placeholders[i]),
                        "{id}: golden placeholders of {text:?}"
                    );
                }
                _ => assert!(placeholders[i].is_null(), "{id}: placeholders of rejected {text:?}"),
            }
        }

        // The same texts through `plan`: PRLOC004 exactly for the rejected ones, no other diagnostic.
        let entries: Vec<String> = texts
            .iter()
            .enumerate()
            .map(|(i, t)| format!("\"t.k{i}\": {}", serde_json::to_string(t).unwrap()))
            .collect();
        let catalog = format!("{{ \"_meta\": {{\"code\":\"en\"}}, {} }}", entries.join(", "));
        let plan = keygen::plan(&[keygen::CatalogInput {
            path: r"C:\x\Languages\en.json".to_owned(),
            content: Some(catalog),
        }]);
        let mut rejected = vec![false; texts.len()];
        let mut other = 0;
        for d in &plan.diagnostics {
            if d.id == keygen::PRLOC004_INVALID_PLACEHOLDER {
                let n: usize = d.message["Text of 't.k".len()..]
                    .split('\'')
                    .next()
                    .unwrap()
                    .parse()
                    .unwrap();
                rejected[n] = true;
            } else {
                other += 1;
            }
        }
        assert_eq!(
            other,
            case["other_diagnostics"].as_array().unwrap().len(),
            "{id}: other diagnostics"
        );
        for (i, r) in rejected.iter().enumerate() {
            assert_eq!(*r, rejects[i].as_bool().unwrap(), "{id}: PRLOC004 of {:?}", texts[i]);
        }
    }
    assert_eq!(fuzz_cases, 2);
}

// ---------------------------------------------------------------------------------------------------------------
// l10n-flat-json
// ---------------------------------------------------------------------------------------------------------------

fn flat_entries(v: &Value) -> Option<Vec<(String, String)>> {
    v.as_array().map(|a| {
        a.iter()
            .map(|p| (p[0].as_str().unwrap().to_owned(), p[1].as_str().unwrap().to_owned()))
            .collect()
    })
}

/// First-occurrence order with the last value (what the runtime catalog does with duplicate names).
fn dedup_last_wins(entries: &[(String, String)]) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    for (k, v) in entries {
        match out.iter_mut().find(|(ok, _)| ok == k) {
            Some(slot) => slot.1 = v.clone(),
            None => out.push((k.clone(), v.clone())),
        }
    }
    out
}

#[test]
fn flat_json_reader_and_runtime_match_the_csharp_oracle() {
    let g = golden::load("l10n-flat-json");
    assert!(g.cases.len() > 2000);
    for case in &g.cases {
        let id = golden::str_of(case, "id");
        let text = golden::str_of(case, "text")
            .replace("{{DEEP_ARRAYS}}", &format!("{}{}", "[".repeat(5000), "]".repeat(5000)));

        // The generator's reader (FlatJsonReader) against the oracle's reflection call.
        let generator = keygen::read_flat_json(&text)
            .ok()
            .map(|entries| entries.into_iter().map(|e| (e.key, e.value)).collect::<Vec<_>>());
        assert_eq!(
            generator,
            flat_entries(&case["generator_flat"]),
            "generator verdict/entries of {id}: {text:?}"
        );

        // The runtime parser against the oracle's System.Text.Json flat verdict (BOM stripped like the loader does).
        let runtime_text = text.strip_prefix('\u{FEFF}').unwrap_or(&text);
        let mut warnings = Vec::new();
        let parsed = LanguageCatalog::try_parse(runtime_text, "t", &mut warnings);
        let invalid_json = warnings.iter().any(|w| w.contains(": invalid JSON ("));
        let unreadable = warnings.iter().any(|w| w.contains(": unreadable text ("));
        let not_object = warnings.iter().any(|w| w.ends_with(": root must be a JSON object"));
        let non_string = warnings.iter().any(|w| w.ends_with("is not a string, ignored"));
        assert_eq!(
            !invalid_json,
            golden::bool_of(case, "json_valid"),
            "json_valid of {id}: {text:?}"
        );
        let stj = flat_entries(&case["stj_flat"]);
        if unreadable && stj.is_some() {
            // The runtime reads every `_meta` name and known string value, the oracle's flat reader never does
            // (contract §2): the only legal divergence, and only inside `_meta`.
            assert!(
                text.contains("_meta"),
                "unreadable text outside _meta in {id}: {text:?}"
            );
            continue;
        }
        let runtime_flat_ok = !invalid_json && !unreadable && !not_object && !non_string;
        assert_eq!(
            runtime_flat_ok,
            stj.is_some(),
            "flat verdict of {id}: {text:?} / {warnings:?}"
        );
        if let (Some(catalog), Some(stj)) = (parsed, stj) {
            assert_eq!(
                catalog.entries(),
                dedup_last_wins(&stj).as_slice(),
                "entries of {id}: {text:?}"
            );
        }
    }
}
